-- Remote readback: catalogs and only the new business schema; no existing user data.
BEGIN READ ONLY;
SET LOCAL statement_timeout='20s';
SET LOCAL search_path=pg_catalog;
SELECT jsonb_build_object(
 'snapshot',(SELECT jsonb_build_object('database',current_database(),'migration_role',current_user,
 'postgres_version',current_setting('server_version'),
 'existing_business_schema',to_regnamespace('dqa_business'),
 'existing_helper_schema',to_regnamespace('dqa_private'),
 'platform_users',to_regclass('auth.users'),
 'platform_identity',to_regprocedure('auth.uid()'),
 'roles',(SELECT jsonb_agg(jsonb_build_object('name',rolname,'superuser',rolsuper,'bypassrls',rolbypassrls) ORDER BY rolname) FROM pg_roles WHERE rolname IN (current_user,'anon','authenticated')),
 'existing_table_counts',(SELECT jsonb_object_agg(schema_name,table_count) FROM (SELECT n.nspname AS schema_name,count(*) AS table_count FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE c.relkind IN ('r','p') AND n.nspname IN ('public','dqa_business','dqa_private') GROUP BY n.nspname) t),
 'btree_gist',(SELECT jsonb_build_object('version',e.extversion,'schema',n.nspname) FROM pg_extension e JOIN pg_namespace n ON n.oid=e.extnamespace WHERE e.extname='btree_gist'),
 'public_definition_fingerprint',(SELECT md5(coalesce(string_agg(object_definition,E'\n' ORDER BY object_definition),'')) FROM (
   SELECT jsonb_build_array('table',c.relname,c.relkind,c.relrowsecurity,c.relforcerowsecurity,c.relacl)::text AS object_definition FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND c.relkind IN ('r','p','v','m','S')
   UNION ALL SELECT jsonb_build_array('column',c.relname,a.attname,format_type(a.atttypid,a.atttypmod),a.attnotnull,pg_get_expr(d.adbin,d.adrelid))::text FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace JOIN pg_attribute a ON a.attrelid=c.oid AND a.attnum>0 AND NOT a.attisdropped LEFT JOIN pg_attrdef d ON d.adrelid=c.oid AND d.adnum=a.attnum WHERE n.nspname='public'
   UNION ALL SELECT jsonb_build_array('constraint',c.relname,k.conname,pg_get_constraintdef(k.oid))::text FROM pg_constraint k JOIN pg_class c ON c.oid=k.conrelid JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public'
   UNION ALL SELECT jsonb_build_array('index',tablename,indexname,indexdef)::text FROM pg_indexes WHERE schemaname='public'
   UNION ALL SELECT jsonb_build_array('policy',tablename,policyname,roles,cmd,qual,with_check)::text FROM pg_policies WHERE schemaname='public'
   UNION ALL SELECT jsonb_build_array('function',p.proname,pg_get_function_identity_arguments(p.oid),p.proacl,pg_get_functiondef(p.oid))::text FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='public' AND p.prokind IN ('f','p','w')
   UNION ALL SELECT jsonb_build_array('trigger',c.relname,t.tgname,pg_get_triggerdef(t.oid))::text FROM pg_trigger t JOIN pg_class c ON c.oid=t.tgrelid JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND NOT t.tgisinternal
 ) definitions)
) AS preflight),
 'migrations',(SELECT jsonb_agg(to_jsonb(m) ORDER BY name) FROM (SELECT name,sha256 FROM dqa_business.schema_migrations) m),
 'tables',(SELECT jsonb_agg(jsonb_build_object('name',c.relname,'rls',c.relrowsecurity,'force_rls',c.relforcerowsecurity) ORDER BY c.relname) FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='dqa_business' AND c.relkind='r'),
 'policies',(SELECT jsonb_agg(to_jsonb(p) ORDER BY tablename,policyname) FROM pg_policies p WHERE schemaname='dqa_business'),
 'constraints',(SELECT jsonb_agg(jsonb_build_object('table',c.relname,'name',k.conname,'type',k.contype,'validated',k.convalidated,'definition',pg_get_constraintdef(k.oid)) ORDER BY c.relname,k.conname) FROM pg_constraint k JOIN pg_class c ON c.oid=k.conrelid JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='dqa_business'),
 'indexes',(SELECT jsonb_agg(to_jsonb(i) ORDER BY tablename,indexname) FROM pg_indexes i WHERE schemaname='dqa_business'),
 'triggers',(SELECT jsonb_agg(jsonb_build_object('table',c.relname,'name',t.tgname,'definition',pg_get_triggerdef(t.oid)) ORDER BY c.relname,t.tgname) FROM pg_trigger t JOIN pg_class c ON c.oid=t.tgrelid JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='dqa_business' AND NOT t.tgisinternal),
 'functions',(SELECT jsonb_agg(jsonb_build_object('name',p.proname,'signature',pg_get_function_identity_arguments(p.oid),'definition',pg_get_functiondef(p.oid),'security_definer',p.prosecdef,'config',p.proconfig,'authenticated_execute',has_function_privilege('authenticated',p.oid,'EXECUTE'),'anon_execute',has_function_privilege('anon',p.oid,'EXECUTE')) ORDER BY p.proname,p.oid) FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='dqa_private'),
 'public_function_grants',(SELECT count(*) FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace CROSS JOIN LATERAL aclexplode(coalesce(p.proacl,acldefault('f',p.proowner))) a WHERE n.nspname='dqa_private' AND a.grantee=0 AND a.privilege_type='EXECUTE'),
 'client_table_privileges',(SELECT jsonb_agg(jsonb_build_object('table',c.relname,'authenticated_select',has_table_privilege('authenticated',c.oid,'SELECT'),'authenticated_mutate',has_table_privilege('authenticated',c.oid,'INSERT,UPDATE,DELETE,TRUNCATE,REFERENCES,TRIGGER'),'anon_any',has_table_privilege('anon',c.oid,'SELECT,INSERT,UPDATE,DELETE,TRUNCATE,REFERENCES,TRIGGER')) ORDER BY c.relname) FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='dqa_business' AND c.relkind='r'),
 'row_counts',(SELECT jsonb_object_agg(name,rows) FROM (SELECT 'approval_events' AS name,count(*) AS rows FROM dqa_business.approval_events UNION ALL SELECT 'artifact_versions' AS name,count(*) AS rows FROM dqa_business.artifact_versions UNION ALL SELECT 'artifacts' AS name,count(*) AS rows FROM dqa_business.artifacts UNION ALL SELECT 'audit_events' AS name,count(*) AS rows FROM dqa_business.audit_events UNION ALL SELECT 'borrows' AS name,count(*) AS rows FROM dqa_business.borrows UNION ALL SELECT 'departments' AS name,count(*) AS rows FROM dqa_business.departments UNION ALL SELECT 'equipment' AS name,count(*) AS rows FROM dqa_business.equipment UNION ALL SELECT 'equipment_port_points' AS name,count(*) AS rows FROM dqa_business.equipment_port_points UNION ALL SELECT 'equipment_ports' AS name,count(*) AS rows FROM dqa_business.equipment_ports UNION ALL SELECT 'import_batches' AS name,count(*) AS rows FROM dqa_business.import_batches UNION ALL SELECT 'import_rows' AS name,count(*) AS rows FROM dqa_business.import_rows UNION ALL SELECT 'lab_operations' AS name,count(*) AS rows FROM dqa_business.lab_operations UNION ALL SELECT 'material_transactions' AS name,count(*) AS rows FROM dqa_business.material_transactions UNION ALL SELECT 'materials' AS name,count(*) AS rows FROM dqa_business.materials UNION ALL SELECT 'memberships' AS name,count(*) AS rows FROM dqa_business.memberships UNION ALL SELECT 'qualifications' AS name,count(*) AS rows FROM dqa_business.qualifications UNION ALL SELECT 'quality_records' AS name,count(*) AS rows FROM dqa_business.quality_records UNION ALL SELECT 'report_versions' AS name,count(*) AS rows FROM dqa_business.report_versions UNION ALL SELECT 'reports' AS name,count(*) AS rows FROM dqa_business.reports UNION ALL SELECT 'request_samples' AS name,count(*) AS rows FROM dqa_business.request_samples UNION ALL SELECT 'requests' AS name,count(*) AS rows FROM dqa_business.requests UNION ALL SELECT 'roles' AS name,count(*) AS rows FROM dqa_business.roles UNION ALL SELECT 'schedule_equipment' AS name,count(*) AS rows FROM dqa_business.schedule_equipment UNION ALL SELECT 'schedules' AS name,count(*) AS rows FROM dqa_business.schedules UNION ALL SELECT 'schema_migrations' AS name,count(*) AS rows FROM dqa_business.schema_migrations UNION ALL SELECT 'settings' AS name,count(*) AS rows FROM dqa_business.settings UNION ALL SELECT 'sites' AS name,count(*) AS rows FROM dqa_business.sites UNION ALL SELECT 'tenants' AS name,count(*) AS rows FROM dqa_business.tenants UNION ALL SELECT 'trial_definitions' AS name,count(*) AS rows FROM dqa_business.trial_definitions) counts)
) AS verification;
COMMIT;
